class ValidationException extends Exception {
    private String campo;

    public ValidationException(String mensaje, String campo) {
        super(mensaje);
        this.campo = campo;
    }

    public String getCampo() {
        return campo;
    }
}

class EmailValidationException extends ValidationException {
    public EmailValidationException(String mensaje) {
        super(mensaje, "email");
    }
}

class AgeValidationException extends ValidationException {
    public AgeValidationException(String mensaje) {
        super(mensaje, "edad");
    }
}

public class ValidadorJerarquico {
    public static void validarUsuario(String email, int edad) throws ValidationException {
        if (email == null) {
            throw new EmailValidationException("El email no puede ser null");
        }
        if (!email.contains("@")) {
            throw new EmailValidationException("El email debe contener '@': " + email);
        }
        if (edad < 0 || edad > 150) {
            throw new AgeValidationException("La edad debe estar entre 0 y 150: " + edad);
        }
        System.out.println("Usuario válido - Email: " + email + ", Edad: " + edad);
    }

    public static void main(String[] args) {
        Object[][] pruebas = {
            {"ana@mail.com", 25},
            {null, 25},
            {"bob", 25},
            {"carlos@mail.com", -5},
            {"diana@mail.com", 200},
            {null, -1}
        };
        for (Object[] prueba : pruebas) {
            try {
                validarUsuario((String) prueba[0], (int) prueba[1]);
            } catch (EmailValidationException e) {
                System.out.println("Error en campo [" + e.getCampo() + "]: " + e.getMessage());
            } catch (AgeValidationException e) {
                System.out.println("Error en campo [" + e.getCampo() + "]: " + e.getMessage());
            } catch (ValidationException e) {
                System.out.println("Error de validación [" + e.getCampo() + "]: " + e.getMessage());
            }
        }
    }
}
